/// <summary>
/// Số dòng HS mỗi trang tiếp theo (chỉ bảng + thead, không quốc hiệu).
/// </summary>
private int GetHtmlMarkRowsContinuationPage()
{
    int iSoMon = dtbClassSubject.Rows.Count;
    if (iSoMon >= 16)
        return 12;
    if (iSoMon >= 10)
        return 15;
    return 18;
