/// <summary>
/// Trang 1 có quốc hiệu, tiêu đề, info → ít dòng hơn để vừa 1 tờ A4 (tránh tràn sang trang chẵn khi Ctrl+P).
/// </summary>
private int GetHtmlMarkRowsFirstPage(bool bolExtraNoteOnFirstPage)
{
    int iCont = GetHtmlMarkRowsContinuationPage();
    int iReduce = bolExtraNoteOnFirstPage ? 6 : 4;
    int iFirst = iCont - iReduce;
    if (iFirst < 8)
        iFirst = 8;
    return iFirst;
}

/// <summary>
/// Trang 1 vừa quốc hiệu vừa chân ký (lớp ít HS).
/// </summary>
private int GetHtmlMarkRowsFirstPageWithFooter(bool bolExtraNoteOnFirstPage)
{
    int iFirst = GetHtmlMarkRowsFirstPage(bolExtraNoteOnFirstPage);
    int iWithFooter = iFirst - 4;
    if (iWithFooter < 6)
        iWithFooter = 6;
    return iWithFooter;
}

/// <summary>
/// Trang cuối có footer ký tên → chừa chỗ phía dưới bảng.
/// </summary>
private int GetHtmlMarkRowsLastPageMax()
{
    int iCont = GetHtmlMarkRowsContinuationPage();
    int iLast = iCont - 4;
    if (iLast < 8)
        iLast = 8;
    return iLast;
}

/// <summary>
/// Tính số dòng từng trang in (trang đầu / giữa / cuối khác nhau).
/// </summary>
private List<int> BuildHtmlMarkPageRowCounts(int intTotal, bool bolLastPageHasFooter, bool bolExtraNoteOnFirstPage)
{
    List<int> lst = new List<int>();
    int intIdx = 0;
    while (intIdx < intTotal)
    {
        int intRemain = intTotal - intIdx;
        int intCap;
        bool bolFirst = (intIdx == 0);

        if (bolFirst)
        {
            intCap = GetHtmlMarkRowsFirstPage(bolExtraNoteOnFirstPage);
            if (bolLastPageHasFooter && intRemain <= GetHtmlMarkRowsFirstPageWithFooter(bolExtraNoteOnFirstPage))
                intCap = GetHtmlMarkRowsFirstPageWithFooter(bolExtraNoteOnFirstPage);
        }
        else
        {
            intCap = GetHtmlMarkRowsContinuationPage();
            if (intCap > intRemain)
                intCap = intRemain;
            if (bolLastPageHasFooter && intRemain <= GetHtmlMarkRowsContinuationPage())
            {
                int intLastMax = GetHtmlMarkRowsLastPageMax();
                if (intRemain > intLastMax)
                    intCap = intRemain - intLastMax;
            }
        }

        if (intCap > intRemain)
            intCap = intRemain;
        if (intCap < 1)
            intCap = intRemain;

        lst.Add(intCap);
        intIdx += intCap;
    }
    return lst;
}

